/// The phrases of a dictionary skill, by slug.
pub fn phrases(slug: &str) -> Option<&'static SkillText> {
    SKILLS.iter().find(|s| s.slug == slug)
}

#[cfg(test)]
mod tests {
    use catalog::Specialization;

    use super::*;

    #[test]
    fn every_typical_skill_has_phrases() {
        for spec in Specialization::ALL {
            for s in crate::typical_skills(*spec) {
                let t = phrases(s).unwrap_or_else(|| panic!("no phrases for {s}"));
                assert!(t.work.len() >= 2 && !t.ask.is_empty(), "{s}");
                assert!(crate::lookup(s).is_some(), "{s} is not a dictionary skill");
            }
        }
        assert!(phrases("cobol").is_none());
    }
}
